import{_ as a,o as r,c as s,a5 as t}from"./chunks/framework.CslsFoWx.js";const o="/VendoraSystem-docs/captures/2026-10-30-hub-local/android-01-kds-temps-reel-magasin.png",n="/VendoraSystem-docs/captures/2026-10-30-hub-local/android-02-kds-reseau-connecte-au-hub-iphone.png",i="/VendoraSystem-docs/captures/2026-10-30-hub-local/android-03-kds-envoi-recu-par-le-hub-serveur-coupe.png",l="/VendoraSystem-docs/captures/2026-10-30-hub-local/android-04-kds-table-9-prete.png",d="/VendoraSystem-docs/captures/2026-10-30-hub-local/android-05-kds-apres-servi-iphone.png",c="/VendoraSystem-docs/captures/2026-10-30-hub-local/ios-01-caisse-hors-ligne-temps-reel-magasin.png",u="/VendoraSystem-docs/captures/2026-10-30-hub-local/ios-02-reglages-reseau-du-magasin-hub-1-connecte.png",p="/VendoraSystem-docs/captures/2026-10-30-hub-local/ios-03-envoi-table-9-hors-ligne.png",g="/VendoraSystem-docs/captures/2026-10-30-hub-local/ios-04-pret-recu-par-le-hub-sans-pull.png",h="/VendoraSystem-docs/captures/2026-10-30-hub-local/ios-05-servi.png",V=JSON.parse('{"title":"Lot 2.6 — Hub temps réel local (spec 10 §4.4, RG-SYNC-18/19/25 ; spec 08 RG-REST-16/17) — 30/10/2026","description":"","frontmatter":{},"headers":[],"relativePath":"preuves/2026-10-30-hub-local.md","filePath":"generated/preuves/2026-10-30-hub-local.md","lastUpdated":null}'),m={name:"preuves/2026-10-30-hub-local.md"};function b(f,e,v,S,y,k){return r(),s("div",null,[...e[0]||(e[0]=[t('<h1 id="lot-2-6-—-hub-temps-reel-local-spec-10-§4-4-rg-sync-18-19-25-spec-08-rg-rest-16-17-—-30-10-2026" tabindex="-1">Lot 2.6 — Hub temps réel local (spec 10 §4.4, RG-SYNC-18/19/25 ; spec 08 RG-REST-16/17) — 30/10/2026 <a class="header-anchor" href="#lot-2-6-—-hub-temps-reel-local-spec-10-§4-4-rg-sync-18-19-25-spec-08-rg-rest-16-17-—-30-10-2026" aria-label="Permalink to &quot;Lot 2.6 — Hub temps réel local (spec 10 §4.4, RG-SYNC-18/19/25 ; spec 08 RG-REST-16/17) — 30/10/2026&quot;">​</a></h1><p class="muted">Dossier <code>docs/captures/2026-10-30-hub-local</code> · 10 image(s) · 0 trace(s)</p><div><p>Vraie stack, <strong>serveur ARRÊTÉ pendant toute la manipulation</strong> (c&#39;est le cas nominal de la spec : internet coupé) : iPhone (simulateur) caisse <code>REGISTER</code> avec omar connecté, Android (émulateur) écran cuisine <code>KDS</code>, même magasin. Aucune adresse saisie : les deux appareils se sont <strong>découverts par mDNS</strong> (Bonjour côté iOS, NSD côté Android — l&#39;émulateur voit les annonces de la machine hôte), ont élu la caisse comme hub, et tout le flux envoi → cuisine → prêt → servi est passé par le relais TCP local.</p><h2 id="ios-—-la-caisse-est-le-hub" tabindex="-1">iOS — la caisse est le hub <a class="header-anchor" href="#ios-—-la-caisse-est-le-hub" aria-label="Permalink to &quot;iOS — la caisse est le hub&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Capture</th><th>Ce qu&#39;il faut voir</th></tr></thead><tbody><tr><td><a href="/VendoraSystem-docs/captures/2026-10-30-hub-local/ios-01-caisse-hors-ligne-temps-reel-magasin.png">ios-01-caisse-hors-ligne-temps-reel-magasin.png</a></td><td>Ligne de synchro « <strong>Hors ligne · temps réel magasin</strong> » (le cloud est injoignable, le magasin fonctionne), « 2 à synchroniser »</td></tr><tr><td><a href="/VendoraSystem-docs/captures/2026-10-30-hub-local/ios-02-reglages-reseau-du-magasin-hub-1-connecte.png">ios-02-reglages-reseau-du-magasin-hub-1-connecte.png</a></td><td>Réglages imprimante → <strong>Réseau du magasin</strong> : « Cet appareil est le hub (port 63953) · <strong>1 connecté(s)</strong> », interrupteur « Caisse principale », champ « Adresse du hub » (vide = découverte automatique)</td></tr><tr><td><a href="/VendoraSystem-docs/captures/2026-10-30-hub-local/ios-03-envoi-table-9-hors-ligne.png">ios-03-envoi-table-9-hors-ligne.png</a></td><td>Table 9 : Croissant « Envoi 1 parti en cuisine » — serveur coupé</td></tr><tr><td><a href="/VendoraSystem-docs/captures/2026-10-30-hub-local/ios-04-pret-recu-par-le-hub-sans-pull.png">ios-04-pret-recu-par-le-hub-sans-pull.png</a></td><td>Le « Prêt » tapé sur le KDS apparaît sur la ligne et le bouton <strong>Servi</strong> — reçu par le LAN, aucun pull possible</td></tr><tr><td><a href="/VendoraSystem-docs/captures/2026-10-30-hub-local/ios-05-servi.png">ios-05-servi.png</a></td><td>Servi → la ligne passe « Servi » ; l&#39;événement repart vers le KDS par le hub</td></tr></tbody></table><h2 id="android-—-l-ecran-cuisine-se-connecte-au-hub" tabindex="-1">Android — l&#39;écran cuisine se connecte au hub <a class="header-anchor" href="#android-—-l-ecran-cuisine-se-connecte-au-hub" aria-label="Permalink to &quot;Android — l&#39;écran cuisine se connecte au hub&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Capture</th><th>Ce qu&#39;il faut voir</th></tr></thead><tbody><tr><td><a href="/VendoraSystem-docs/captures/2026-10-30-hub-local/android-01-kds-temps-reel-magasin.png">android-01-kds-temps-reel-magasin.png</a></td><td>« Hors ligne — dernière synchro jamais <strong>· temps réel magasin</strong> », bouton <strong>Réseau</strong></td></tr><tr><td><a href="/VendoraSystem-docs/captures/2026-10-30-hub-local/android-02-kds-reseau-connecte-au-hub-iphone.png">android-02-kds-reseau-connecte-au-hub-iphone.png</a></td><td>Boîte « Réseau du magasin » : « <strong>Temps réel magasin actif · hub 367bf296-…</strong> » (l&#39;iPhone), champ d&#39;adresse imposée</td></tr><tr><td><a href="/VendoraSystem-docs/captures/2026-10-30-hub-local/android-03-kds-envoi-recu-par-le-hub-serveur-coupe.png">android-03-kds-envoi-recu-par-le-hub-serveur-coupe.png</a></td><td><strong>Table 9 · Envoi 1 · Reçu</strong> arrivé par le hub</td></tr><tr><td><a href="/VendoraSystem-docs/captures/2026-10-30-hub-local/android-04-kds-table-9-prete.png">android-04-kds-table-9-prete.png</a></td><td>Commencer → Prêt sur le KDS</td></tr><tr><td><a href="/VendoraSystem-docs/captures/2026-10-30-hub-local/android-05-kds-apres-servi-iphone.png">android-05-kds-apres-servi-iphone.png</a></td><td>Après le « Servi » fait sur l&#39;iPhone : la table 9 a quitté la file (reçu par le hub)</td></tr></tbody></table><h2 id="mesures-journal-pos-hub-de-l-emulateur-horloge-du-mac" tabindex="-1">Mesures (journal <code>pos.hub</code> de l&#39;émulateur, horloge du Mac) <a class="header-anchor" href="#mesures-journal-pos-hub-de-l-emulateur-horloge-du-mac" aria-label="Permalink to &quot;Mesures (journal `pos.hub` de l&#39;émulateur, horloge du Mac)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Instant</th><th>Événement</th></tr></thead><tbody><tr><td>01:03:22</td><td>KDS démarre, « je suis le hub » (seul)</td></tr><tr><td>01:03:35</td><td>pair iPhone découvert (mDNS) → <strong>élection : hub = iPhone</strong> (REGISTER &gt; KDS)</td></tr><tr><td>01:03:36</td><td>connecté au hub, <strong>rattrapage : 1 événement</strong> (la connexion d&#39;omar, faite avant que le KDS n&#39;arrive)</td></tr><tr><td>01:05:29.664</td><td>tap « Envoyer en cuisine » sur l&#39;iPhone (horodatage juste avant le tap)</td></tr><tr><td>01:05:29.939</td><td><code>REÇOIT OrderLinesSent</code> sur le KDS → <strong>≤ 275 ms</strong> (RG-REST-16 : &lt; 2 s)</td></tr><tr><td>01:06:32</td><td><code>REÇOIT OrderStatusChanged</code> (le « Servi » de l&#39;iPhone)</td></tr></tbody></table><p>Chaque appareil a gardé <strong>sa propre outbox</strong> (« 2 à synchroniser » sur l&#39;iPhone) : le hub n&#39;a rien confirmé, le cloud le fera au retour du réseau, et la dédup <code>applied_event</code> ignorera ce qu&#39;il renverra (RG-SYNC-03/18).</p><h2 id="deux-defauts-trouves-sur-la-vraie-stack-corriges" tabindex="-1">Deux défauts trouvés sur la vraie stack, corrigés <a class="header-anchor" href="#deux-defauts-trouves-sur-la-vraie-stack-corriges" aria-label="Permalink to &quot;Deux défauts trouvés sur la vraie stack, corrigés&quot;">​</a></h2><ol><li><strong>Annonce Bonjour refusée (-72004)</strong> : le nom d&#39;instance « pos-&lt;storeId&gt;-&lt;deviceId&gt; » avec deux UUID fait 77 octets, DNS-SD en accepte 63 (Android le tronquait silencieusement, iOS refusait). Nom raccourci au préfixe du magasin ; le <code>storeId</code> complet reste vérifié dans le TXT.</li><li><strong>Annonce qui « disparaît » toutes les ~25 s</strong> (vue de l&#39;émulateur) : le KDS lâchait un hub pourtant connecté et se ré-élisait, puis se reconnectait 6 s plus tard. Désormais une connexion vivante fait foi : seul le silence de 15 s du heartbeat (RG-SYNC-19) déclenche la ré-élection.</li></ol><p>Observation : l&#39;émulateur a affiché « Process system isn&#39;t responding » (ANR du <em>système</em> de l&#39;émulateur, Mac chargé par les builds) — sans rapport avec l&#39;app, qui n&#39;a jamais été interrompue.</p></div><h2 id="galerie" tabindex="-1">Galerie <a class="header-anchor" href="#galerie" aria-label="Permalink to &quot;Galerie&quot;">​</a></h2><div class="proof-grid"><figure class="proof"><a href="/VendoraSystem-docs/captures/2026-10-30-hub-local/android-01-kds-temps-reel-magasin.png" target="_blank"><img src="'+o+'" alt="android-01-kds-temps-reel-magasin.png" loading="lazy"></a><figcaption>android-01-kds-temps-reel-magasin.png</figcaption></figure><figure class="proof"><a href="/VendoraSystem-docs/captures/2026-10-30-hub-local/android-02-kds-reseau-connecte-au-hub-iphone.png" target="_blank"><img src="'+n+'" alt="android-02-kds-reseau-connecte-au-hub-iphone.png" loading="lazy"></a><figcaption>android-02-kds-reseau-connecte-au-hub-iphone.png</figcaption></figure><figure class="proof"><a href="/VendoraSystem-docs/captures/2026-10-30-hub-local/android-03-kds-envoi-recu-par-le-hub-serveur-coupe.png" target="_blank"><img src="'+i+'" alt="android-03-kds-envoi-recu-par-le-hub-serveur-coupe.png" loading="lazy"></a><figcaption>android-03-kds-envoi-recu-par-le-hub-serveur-coupe.png</figcaption></figure><figure class="proof"><a href="/VendoraSystem-docs/captures/2026-10-30-hub-local/android-04-kds-table-9-prete.png" target="_blank"><img src="'+l+'" alt="android-04-kds-table-9-prete.png" loading="lazy"></a><figcaption>android-04-kds-table-9-prete.png</figcaption></figure><figure class="proof"><a href="/VendoraSystem-docs/captures/2026-10-30-hub-local/android-05-kds-apres-servi-iphone.png" target="_blank"><img src="'+d+'" alt="android-05-kds-apres-servi-iphone.png" loading="lazy"></a><figcaption>android-05-kds-apres-servi-iphone.png</figcaption></figure><figure class="proof"><a href="/VendoraSystem-docs/captures/2026-10-30-hub-local/ios-01-caisse-hors-ligne-temps-reel-magasin.png" target="_blank"><img src="'+c+'" alt="ios-01-caisse-hors-ligne-temps-reel-magasin.png" loading="lazy"></a><figcaption>ios-01-caisse-hors-ligne-temps-reel-magasin.png</figcaption></figure><figure class="proof"><a href="/VendoraSystem-docs/captures/2026-10-30-hub-local/ios-02-reglages-reseau-du-magasin-hub-1-connecte.png" target="_blank"><img src="'+u+'" alt="ios-02-reglages-reseau-du-magasin-hub-1-connecte.png" loading="lazy"></a><figcaption>ios-02-reglages-reseau-du-magasin-hub-1-connecte.png</figcaption></figure><figure class="proof"><a href="/VendoraSystem-docs/captures/2026-10-30-hub-local/ios-03-envoi-table-9-hors-ligne.png" target="_blank"><img src="'+p+'" alt="ios-03-envoi-table-9-hors-ligne.png" loading="lazy"></a><figcaption>ios-03-envoi-table-9-hors-ligne.png</figcaption></figure><figure class="proof"><a href="/VendoraSystem-docs/captures/2026-10-30-hub-local/ios-04-pret-recu-par-le-hub-sans-pull.png" target="_blank"><img src="'+g+'" alt="ios-04-pret-recu-par-le-hub-sans-pull.png" loading="lazy"></a><figcaption>ios-04-pret-recu-par-le-hub-sans-pull.png</figcaption></figure><figure class="proof"><a href="/VendoraSystem-docs/captures/2026-10-30-hub-local/ios-05-servi.png" target="_blank"><img src="'+h+'" alt="ios-05-servi.png" loading="lazy"></a><figcaption>ios-05-servi.png</figcaption></figure></div>',5)])])}const R=a(m,[["render",b]]);export{V as __pageData,R as default};
